class IntMap {
  private static B = 2069; // prime bucket count
  private buckets: [number, number][][] = Array.from({ length: IntMap.B }, () => []);

  private bucket(key: number): [number, number][] {
    return this.buckets[key % IntMap.B];
  }

  put(key: number, value: number): void {
    const b = this.bucket(key);
    for (const pair of b) if (pair[0] === key) { pair[1] = value; return; }
    b.push([key, value]);
  }

  get(key: number): number {
    for (const [k, v] of this.bucket(key)) if (k === key) return v;
    return -1;
  }

  remove(key: number): void {
    const b = this.bucket(key);
    for (let i = 0; i < b.length; i++) {
      if (b[i][0] === key) {
        b[i] = b[b.length - 1]; // order inside a bucket does not matter
        b.pop();
        return;
      }
    }
  }
}

