            if k == key:
                return v
        return -1

    def remove(self, key: int) -> None:
        b = self.buckets[key % self.B]
        for i, pair in enumerate(b):
            if pair[0] == key:
                b[i] = b[-1]  # order inside a bucket does not matter
                b.pop()
                return

